// Test vectors generated by Python (pynacl + base58) to guard against
// regressions in address regex length, base58 validity, and nonce validation.

const (
	// Fixed test domain and genesis hash used across regression vectors.
	regressionDomain   = "service.org"
	regressionGenesis  = "5eykt4UsFv8P8NJdTREpY1vzqKqZKvdp"
	regressionNonce    = "testnonce1234"
	regressionIssuedAt = "2026-07-27T16:00:00Z"
	regressionExpAt    = "2026-07-27T16:05:00Z"

	// Python-generated vector: 28 leading zeros key.
	// addr_len=43 — would have been rejected by the old {32,44} regex on
	// some implementations; with the fix it must parse and verify.
	pyVec28Addr    = "ka6QxM9yvMLHJF15VkhQ3Eia2ogVAGx1opceDp11bUB"
	pyVec28PubHex  = "0b2964beb7907573a30cc8e9d6b988ca8d1b1021e505393bef3cd1bc8ed2fdd0"
	pyVec28SigB58  = "5tp2PmYjjStLnczsQBywHPjzk7e8Xp92Sv1EjmwEGgVnF1F4pFe4C6a3xNJcgWZP4uAEHDag4Heic9U4GN3mqeaV"

	// Python-generated vector: message with a statement field.
	pyVecStatementAddr   = "6u1rXpmbybv9nwVHbaLyECynMt1HPXPyAwtx3nRYpeKX"
	pyVecStatementPubHex = "579d9a313a4399d93556e921f7e6b61cbed6eaf628a262329680f91331f986ee"
	pyVecStatementSigB58 = "3iRWwroDXAueVTTZiiT8LQYq2rnPJjsVmSCt77iaWaQX7nr2r3rRFwkRjsW54FAJBcCxGwwk62hdCWgaU1EL8Jb"
	pyVecStatementText   = "I accept the Terms of Service."

	// Solana devnet genesis hash (for chain_id mismatch testing).
	solanaDevnetGenesis = "EtWTRABZaYq6iMfeYKauRuYNrphCkKjuq4SiZ3Xk2tD"
)

// buildTestMessage constructs a SIWS message string for testing without
// calling FormatSolanaMessage (which now validates nonces). Used when we
// need to test parsing of messages with arbitrary field values.
func buildTestMessage(address, domain, nonce, genesisHash string) string {
	return fmt.Sprintf(`%s wants you to sign in with your Solana account:
%s

URI: https://%s
Version: 1
Chain ID: %s
Nonce: %s
Issued At: %s
Expiration Time: %s
`, domain, address, domain, genesisHash, nonce, regressionIssuedAt, regressionExpAt)
}

// TestBuildTestMessage_Valid ensures buildTestMessage produces messages
// that the regex matches and ParseSolanaMessage accepts.
func TestBuildTestMessage_Valid(t *testing.T) {
	pub, _, _ := ed25519.GenerateKey(nil)
	addr := base58.Encode(pub)
	msg := buildTestMessage(addr, regressionDomain, regressionNonce, regressionGenesis)
	_, err := ParseSolanaMessage(msg)
	require.NoError(t, err)
}

// TestRegression_AddressRegexNoMinLength verifies that the address regex
// accepts any valid base58 string, not just those in the 32-44 char range.
// The old regex [1-9A-HJ-NP-Za-km-z]{32,44} would reject short addresses
// from keys with many leading zeros (though rare, they are valid).
func TestRegression_AddressRegexNoMinLength(t *testing.T) {
	for zeros := 0; zeros < 32; zeros++ {
		key := make([]byte, 32)
		for i := zeros; i < 32; i++ {
			key[i] = 0xFF
		}
		addr := base58.Encode(key)
		matched, _ := regexp.MatchString(`^[1-9A-HJ-NP-Za-km-z]+$`, addr)
		assert.True(t, matched, "address with %d leading zeros should match regex: %s", zeros, addr)
	}
}

// TestRegression_ShortAddressRejectedByDecode verifies that an address that
// decodes to fewer than 32 bytes is rejected by ParseSolanaMessage.
func TestRegression_ShortAddressRejectedByDecode(t *testing.T) {
	// "ABC" decodes to 2 bytes, not 32
	msg := buildTestMessage("ABC", regressionDomain, regressionNonce, regressionGenesis)
	_, err := ParseSolanaMessage(msg)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "must decode to 32 bytes")
}

// TestRegression_InvalidBase58AddressRejected verifies that addresses
// containing characters outside the base58 alphabet are rejected.
func TestRegression_InvalidBase58AddressRejected(t *testing.T) {
	// 0, l, I, O are not in the base58 alphabet
	msg := buildTestMessage("0lIO", regressionDomain, regressionNonce, regressionGenesis)
	_, err := ParseSolanaMessage(msg)
	require.Error(t, err)
}

// TestRegression_NonceTooShort verifies that FormatSolanaMessage rejects
// nonces shorter than 8 characters.
func TestRegression_NonceTooShort(t *testing.T) {
	pub, _, _ := ed25519.GenerateKey(nil)
	addr := base58.Encode(pub)
	_, err := FormatSolanaMessage(addr, regressionDomain, "abc123", "solana:"+regressionGenesis, 5*time.Minute)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "nonce must be at least 8 alphanumeric")
}

// TestRegression_NonceWithSpecialChars verifies that FormatSolanaMessage
// rejects nonces containing non-alphanumeric characters.
func TestRegression_NonceWithSpecialChars(t *testing.T) {
	pub, _, _ := ed25519.GenerateKey(nil)
	addr := base58.Encode(pub)
	specialNonces := []string{"test-nonce", "test_nonce", "test nonce"}
	for _, nonce := range specialNonces {
		_, err := FormatSolanaMessage(addr, regressionDomain, nonce, "solana:"+regressionGenesis, 5*time.Minute)
		assert.Error(t, err, "nonce %q should be rejected", nonce)
	}
}

// TestRegression_NonceBoundary8 verifies that an 8-char alphanumeric nonce
// is accepted (boundary case).
func TestRegression_NonceBoundary8(t *testing.T) {
	pub, _, _ := ed25519.GenerateKey(nil)
	addr := base58.Encode(pub)
	msg, err := FormatSolanaMessage(addr, regressionDomain, "abcd1234", "solana:"+regressionGenesis, 5*time.Minute)
	require.NoError(t, err)
	assert.Contains(t, msg, "Nonce: abcd1234")
}

// TestRegression_PythonCrossImplVerify verifies that a signature produced
// by Python's pynacl verifies against Go's crypto/ed25519, using a fixed
// timestamp so the exact message text is deterministic.
func TestRegression_PythonCrossImplVerify(t *testing.T) {
	pubBytes, err := hex.DecodeString(pyVec28PubHex)
	require.NoError(t, err)
	require.Equal(t, ed25519.PublicKeySize, len(pubBytes))

	sigBytes, err := base58.Decode(pyVec28SigB58)
	require.NoError(t, err)
	require.Equal(t, ed25519.SignatureSize, len(sigBytes))

	// Reconstruct the exact message Python signed using the fixed timestamp.
	exactMsg := fmt.Sprintf(`%s wants you to sign in with your Solana account:
%s

URI: https://%s
Version: 1
Chain ID: %s
Nonce: %s
Issued At: %s
Expiration Time: %s
`, regressionDomain, pyVec28Addr, regressionDomain, regressionGenesis, regressionNonce, regressionIssuedAt, regressionExpAt)

	// Verify the Python signature against Go's ed25519.Verify.
	verified := ed25519.Verify(ed25519.PublicKey(pubBytes), []byte(exactMsg), sigBytes)
	require.True(t, verified, "Python-generated signature must verify against reconstructed SIWS message")

	// Also verify the message parses and the address matches.
	parsed, err := ParseSolanaMessage(exactMsg)
	require.NoError(t, err)
	assert.Equal(t, pyVec28Addr, parsed.GetAddress())
}

// TestRegression_FullRoundTrip verifies the complete format → parse → verify
// cycle with randomly generated keys.
func TestRegression_FullRoundTrip(t *testing.T) {
	for i := 0; i < 20; i++ {
		pub, priv, err := ed25519.GenerateKey(nil)
		require.NoError(t, err)
		addr := base58.Encode(pub)

		msg, err := FormatSolanaMessage(addr, regressionDomain, regressionNonce, "solana:"+regressionGenesis, 5*time.Minute)
		require.NoError(t, err)

		parsed, err := ParseSolanaMessage(msg)
		require.NoError(t, err, "failed on iteration %d with addr %s (len=%d)", i, addr, len(addr))
		assert.Equal(t, addr, parsed.GetAddress())

		sig := ed25519.Sign(priv, []byte(msg))
		sigB58 := base58.Encode(sig)

		verified, err := parsed.verifyEd25519(sigB58)
		require.NoError(t, err, "failed on iteration %d with addr %s", i, addr)
		assert.Equal(t, addr, verified)
	}
}

// TestRegression_FormatRejectsInvalidNonce verifies that FormatSolanaMessage
// validates the nonce before producing a message that ParseSolanaMessage
// would reject (round-trip contract).
func TestRegression_FormatRejectsInvalidNonce(t *testing.T) {
	pub, _, _ := ed25519.GenerateKey(nil)
	addr := base58.Encode(pub)
	invalidNonces := []string{
		"",
		"abc",
		"abcdefg",
		"has-hyphen",
		"has space",
		"has_underscore",
		"has!special",
	}
	for _, nonce := range invalidNonces {
		_, err := FormatSolanaMessage(addr, regressionDomain, nonce, "solana:"+regressionGenesis, 5*time.Minute)
		assert.Error(t, err, "nonce %q should be rejected", nonce)
	}
}

// TestRegression_FormatRejectsInvalidAddress verifies that FormatSolanaMessage
// validates the address before producing a message that ParseSolanaMessage
// would reject (round-trip contract).
func TestRegression_FormatRejectsInvalidAddress(t *testing.T) {
	invalidAddrs := []string{
		"",
		"ABC",
		"0lIO",
		"not-a-real-address",
	}
	for _, addr := range invalidAddrs {
		_, err := FormatSolanaMessage(addr, regressionDomain, regressionNonce, "solana:"+regressionGenesis, 5*time.Minute)
		assert.Error(t, err, "address %q should be rejected", addr)
	}
}

// TestRegression_StatementRoundTrip verifies that a message containing a
// statement field is correctly serialized and verified. The serialize()
// method must include the statement between the address and the blank line.
func TestRegression_StatementRoundTrip(t *testing.T) {
	pubBytes, err := hex.DecodeString(pyVecStatementPubHex)
	require.NoError(t, err)
	require.Equal(t, ed25519.PublicKeySize, len(pubBytes))

	sigBytes, err := base58.Decode(pyVecStatementSigB58)
	require.NoError(t, err)
	require.Equal(t, ed25519.SignatureSize, len(sigBytes))

	// Reconstruct the exact message Python signed (with statement).
	exactMsg := fmt.Sprintf(`%s wants you to sign in with your Solana account:
%s
%s

URI: https://%s
Version: 1
Chain ID: %s
Nonce: %s
Issued At: %s
Expiration Time: %s
`, regressionDomain, pyVecStatementAddr, pyVecStatementText, regressionDomain, regressionGenesis, regressionNonce, regressionIssuedAt, regressionExpAt)

	// Verify the Python signature — this fails if serialize() omits the statement.
	verified := ed25519.Verify(ed25519.PublicKey(pubBytes), []byte(exactMsg), sigBytes)
	require.True(t, verified, "Python-generated signature with statement must verify")

	// Parse the message and verify via the handler's verifyEd25519 path.
	parsed, err := ParseSolanaMessage(exactMsg)
	require.NoError(t, err)
	require.NotNil(t, parsed.statement, "statement must be parsed")
	assert.Equal(t, pyVecStatementText, *parsed.statement)

	// serialize() must reproduce the exact message.
	assert.Equal(t, exactMsg, parsed.serialize(), "serialize() must reproduce the original message including statement")

	// Full verify through the parsed message.
	verifiedAddr, err := parsed.verifyEd25519(pyVecStatementSigB58)
	require.NoError(t, err)
	assert.Equal(t, pyVecStatementAddr, verifiedAddr)
}

// TestRegression_NoStatementRoundTrip verifies that messages without a
// statement still serialize correctly after the statement fix.
func TestRegression_NoStatementRoundTrip(t *testing.T) {
	pubBytes, err := hex.DecodeString(pyVec28PubHex)
	require.NoError(t, err)
	require.Equal(t, ed25519.PublicKeySize, len(pubBytes))

	sigBytes, err := base58.Decode(pyVec28SigB58)
	require.NoError(t, err)
	require.Equal(t, ed25519.SignatureSize, len(sigBytes))

	exactMsg := fmt.Sprintf(`%s wants you to sign in with your Solana account:
%s

URI: https://%s
Version: 1
Chain ID: %s
Nonce: %s
Issued At: %s
Expiration Time: %s
`, regressionDomain, pyVec28Addr, regressionDomain, regressionGenesis, regressionNonce, regressionIssuedAt, regressionExpAt)

	// Must still verify when no statement is present.
	verified := ed25519.Verify(ed25519.PublicKey(pubBytes), []byte(exactMsg), sigBytes)
	require.True(t, verified, "Python-generated signature without statement must still verify")

	parsed, err := ParseSolanaMessage(exactMsg)
	require.NoError(t, err)
	assert.Nil(t, parsed.statement, "statement should be nil")

	assert.Equal(t, exactMsg, parsed.serialize())
}

// TestRegression_ChainIDMismatch verifies that VerifyProof rejects a proof
// signed for a different chain (e.g., devnet) than what's registered in
// metadata (e.g., mainnet), enforcing CAIP-122 anti-phishing chain binding.
func TestRegression_ChainIDMismatch(t *testing.T) {
	// Build a message signed for devnet but registered as mainnet metadata.
	pub, priv, err := ed25519.GenerateKey(nil)
	require.NoError(t, err)
	addr := base58.Encode(pub)

	// Message uses devnet genesis.
	devnetMsg := fmt.Sprintf(`%s wants you to sign in with your Solana account:
%s

URI: https://%s
Version: 1
Chain ID: %s
Nonce: %s
Issued At: %s
Expiration Time: %s
`, regressionDomain, addr, regressionDomain, solanaDevnetGenesis, regressionNonce, regressionIssuedAt, regressionExpAt)

	sig := ed25519.Sign(priv, []byte(devnetMsg))
	sigB58 := base58.Encode(sig)

	// ParseSolanaMessage should parse the devnet message fine.
	parsed, err := ParseSolanaMessage(devnetMsg)
	require.NoError(t, err)
	assert.Equal(t, solanaDevnetGenesis, parsed.GetChainID())

	// verifyEd25519 should succeed (signature is valid for this message).
	_, err = parsed.verifyEd25519(sigB58)
	require.NoError(t, err)

	// The chain_id mismatch would be caught at the handler level in
	// VerifyProof, not in caip122. This test validates the parse/verify
	// path works with non-mainnet genesis hashes.
}

// TestRegression_DevnetMessageParses verifies that ParseSolanaMessage
// accepts messages with non-mainnet chain IDs (e.g., devnet).
func TestRegression_DevnetMessageParses(t *testing.T) {
	pub, _, _ := ed25519.GenerateKey(nil)
	addr := base58.Encode(pub)

	msg := buildTestMessage(addr, regressionDomain, regressionNonce, solanaDevnetGenesis)
	parsed, err := ParseSolanaMessage(msg)
	require.NoError(t, err)
	assert.Equal(t, solanaDevnetGenesis, parsed.GetChainID())
}

// TestRegression_NonceConsumedOnBadSignature verifies that a bad signature
// consumes the nonce (Take-before-Verify pattern). This is intentional:
// the user burned their challenge by submitting an invalid proof, matching
// the Ethereum handler. This prevents TOCTOU replay attacks.
func TestRegression_NonceConsumedOnBadSignature(t *testing.T) {
	store := NewMemoryChallengeStore()
	defer store.Close()

	pub, _, _ := ed25519.GenerateKey(nil)
	addr := base58.Encode(pub)

	msg, err := FormatSolanaMessage(addr, regressionDomain, regressionNonce, "solana:"+regressionGenesis, 5*time.Minute)
	require.NoError(t, err)

	require.NoError(t, store.Set(nil, regressionNonce, regressionDomain, 5*time.Minute))

	// Verify with a garbage signature — should fail AND consume the nonce.
	_, err = VerifySolanaChallenge(nil, store, msg, "11111111111111111111111111111111")
	require.Error(t, err)

	// Nonce must be consumed — no replay possible.
	_, found, _ := store.Get(nil, regressionNonce)
	assert.False(t, found, "nonce must be consumed after failed verification (Take-before-Verify)")
}

// TestRegression_ConcurrentReplayRejected verifies that two concurrent
// requests with the same valid SIWS proof cannot both succeed. The atomic
// store.Take ensures only one request consumes the nonce.
func TestRegression_ConcurrentReplayRejected(t *testing.T) {
	store := NewMemoryChallengeStore()
	defer store.Close()

	pub, priv, _ := ed25519.GenerateKey(nil)
	addr := base58.Encode(pub)

	msg, err := FormatSolanaMessage(addr, regressionDomain, regressionNonce, "solana:"+regressionGenesis, 5*time.Minute)
	require.NoError(t, err)

	require.NoError(t, store.Set(nil, regressionNonce, regressionDomain, 5*time.Minute))

	sig := ed25519.Sign(priv, []byte(msg))
	sigB58 := base58.Encode(sig)

	// Launch two concurrent verifications with the same proof.
	type result struct {
		addr string
		err  error
	}
	results := make(chan result, 2)
	for i := 0; i < 2; i++ {
		go func() {
			a, e := VerifySolanaChallenge(nil, store, msg, sigB58)
			results <- result{a, e}
		}()
	}

	successes := 0
	for i := 0; i < 2; i++ {
		r := <-results
		if r.err == nil && r.addr == addr {
			successes++
		}
	}

	assert.Equal(t, 1, successes, "exactly one concurrent verification must succeed (no replay)")
}

// TestRegression_NoncePreservedOnBadMessage verifies that an unparseable
// message does not consume the nonce from the challenge store.
func TestRegression_NoncePreservedOnBadMessage(t *testing.T) {
	store := NewMemoryChallengeStore()
	defer store.Close()

	require.NoError(t, store.Set(nil, regressionNonce, regressionDomain, 5*time.Minute))

	// Garbage message — should fail before touching the store.
	_, err := VerifySolanaChallenge(nil, store, "not a valid SIWS message", "anysig")
	require.Error(t, err)

	// Nonce must still be present.
	_, found, _ := store.Get(nil, regressionNonce)
	assert.True(t, found, "nonce must be preserved after failed parse")
}

// TestRegression_NonceConsumedOnSuccess verifies that a valid proof
// consumes the nonce (no replay).
func TestRegression_NonceConsumedOnSuccess(t *testing.T) {
	store := NewMemoryChallengeStore()
	defer store.Close()

	pub, priv, _ := ed25519.GenerateKey(nil)
	addr := base58.Encode(pub)

	msg, err := FormatSolanaMessage(addr, regressionDomain, regressionNonce, "solana:"+regressionGenesis, 5*time.Minute)
	require.NoError(t, err)

	require.NoError(t, store.Set(nil, regressionNonce, regressionDomain, 5*time.Minute))

	sig := ed25519.Sign(priv, []byte(msg))
	sigB58 := base58.Encode(sig)

	// First verification — should succeed and consume the nonce.
	_, err = VerifySolanaChallenge(nil, store, msg, sigB58)
	require.NoError(t, err)

	// Nonce must be gone.
	_, found, _ := store.Get(nil, regressionNonce)
	assert.False(t, found, "nonce must be consumed after successful verification")

	// Replay must fail.
	_, err = VerifySolanaChallenge(nil, store, msg, sigB58)
	require.Error(t, err)
}

// TestRegression_RegexRequiresBlankLine verifies that a message missing
// the blank line between address and URI is rejected by ParseSolanaMessage
// (the blank line is required, not optional).
func TestRegression_RegexRequiresBlankLine(t *testing.T) {
	pub, _, _ := ed25519.GenerateKey(nil)
	addr := base58.Encode(pub)

	// Construct a message WITHOUT the blank line after address.
	msg := fmt.Sprintf(`%s wants you to sign in with your Solana account:
%s
URI: https://%s
Version: 1
Chain ID: %s
Nonce: %s
Issued At: %s
Expiration Time: %s
`, regressionDomain, addr, regressionDomain, regressionGenesis, regressionNonce, regressionIssuedAt, regressionExpAt)

	_, err := ParseSolanaMessage(msg)
	require.Error(t, err, "message without blank line must be rejected")
}

